const int MOD = 1E9+7;

const int N = 1000+5;

const int dx[] = {-1,1,0,0,-1,-1,1,1};

const int dy[] = {0,0,-1,1,-1,1,-1,1};

using namespace std;

LL a[10000];

int main()

{

    int n;

    scanf("%d",&n);

    for(int i=1; i<=n; i++)

    {

        scanf("%lld",&a[i]);

    }

    LL ans=0;

    while(true)

    {

        LL maxn=a[1];

        int id=1;

        for(int i=2; i<=n; i++)

        {

            if(maxn<a[i])

            {

                maxn=a[i];

                id=i;//---

            }

        }

        if(maxn<=n-1)

            break;////////------

        for(int i=1; i<=n; i++)

        {

            if(i==id)

            {

                a[i]=maxn%n;



            }

            else

            {

                a[i]+=maxn/n;

            }

        }

        ans+=maxn/n;//

    }

    printf("%lld
",ans);

}

